const statistics = $json.statistics || {};
const snippet = $json.snippet || {};
const contentDetails = $json.contentDetails || {};

const views = Number(statistics.viewCount || 0);
const likes = Number(statistics.likeCount || 0);
const comments = Number(statistics.commentCount || 0);

// Engagement rates
const likeRate = views > 0 ? likes / views : 0;
const commentRate = views > 0 ? comments / views : 0;

// Weighted engagement score
const engagementScore =
  (likeRate * 100) * 0.7 +
  (commentRate * 100) * 0.3;

// Normalize raw popularity
// log prevents huge channels from dominating everything
const popularityScore = Math.log10(views + 1);

// Combined score
const finalScore =
  popularityScore * 0.4 +
  engagementScore * 0.6;

// Duration
const duration = contentDetails.duration || "PT0S";

const match = duration.match(
  /PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/
);

const hours = Number(match?.[1] || 0);
const minutes = Number(match?.[2] || 0);
const seconds = Number(match?.[3] || 0);

const durationSeconds =
  hours * 3600 +
  minutes * 60 +
  seconds;

// Basic quality filters
const hasEnoughViews = views >= 500;
const hasEngagement = likes >= 5 || comments >= 1;
const validDuration = durationSeconds >= 30 && durationSeconds <= 3600;

// Final decision
const shouldProcess =
  hasEnoughViews &&
  hasEngagement &&
  validDuration;

return {
  json: {
    videoId: $json.id,

    title: snippet.title,
    channelTitle: snippet.channelTitle,
    publishedAt: snippet.publishedAt,

    views,
    likes,
    comments,

    likeRate,
    commentRate,
    engagementScore,
    popularityScore,
    finalScore,

    durationSeconds,

    shouldProcess
  }
};

let output = "";

for (const item of $input.all()) {
  const title = item.json.data?.video_title || "Untitled";
  const transcript = item.json.data?.transcript?.text || "";

  output += `${title}\n\n${transcript}\n\n\n`;
}

return [
  {
    json: {
      text: output
    }
  }
];

const htmlContent = $json.data;

return {
  json: {},
  binary: {
    data: {
      data: Buffer.from(htmlContent, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'AI_News_Digest.html'
    }
  }
};
